import React, { ReactNode } from 'react';

// Base props that all variants share
interface BaseAlertProps {
  children: ReactNode;
  onClose?: () => void;
}

// Discriminated union: type determines which props are available
type AlertProps = 
  | (BaseAlertProps & { type: 'info'; title?: string })
  | (BaseAlertProps & { type: 'error'; errorCode: string; title: string })
  | (BaseAlertProps & { type: 'success'; autoDismiss?: boolean });

const Alert: React.FC<AlertProps> = (props) => {
  const { type, children, onClose } = props;

  return (
    <div className={`alert alert--${type}`} role="alert">
      {type === 'error' && <span className="error-code">{props.errorCode}</span>}
      {props.title && <h4>{props.title}</h4>}
      <div>{children}</div>
      {onClose && <button onClick={onClose}>×</button>}
    </div>
  );
};

import React, { useState, FormEvent, ChangeEvent } from 'react';

interface FormData {
  email: string;
  password: string;
}

const LoginForm: React.FC = () => {
  const [formData, setFormData] = useState<FormData>({
    email: '',
    password: ''
  });

  const handleChange = (e: ChangeEvent<HTMLInputElement>): void => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: FormEvent<HTMLFormElement>): void => {
    e.preventDefault();
    console.log('Submitting:', formData);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="email"
        name="email"
        value={formData.email}
        onChange={handleChange}
        placeholder="Email"
      />
      <input
        type="password"
        name="password"
        value={formData.password}
        onChange={handleChange}
        placeholder="Password"
      />
      <button type="submit">Login</button>
    </form>
  );
};

import React, { ButtonHTMLAttributes } from 'react';

// Extend native button props while adding custom ones
interface IconButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  icon: React.ReactNode;
  iconPosition?: 'left' | 'right';
}

const IconButton: React.FC<IconButtonProps> = ({ 
  icon, 
  iconPosition = 'left', 
  children, 
  ...rest 
}) => {
  return (
    <button {...rest} className={`icon-btn icon-btn--${iconPosition}`}>
      {iconPosition === 'left' && icon}
      {children}
      {iconPosition === 'right' && icon}
    </button>
  );
};

// Usage: all standard button attributes work + custom props
<IconButton 
  icon={<span>→</span>} 
  iconPosition="right"
  onClick={() => alert('Clicked!')}
  disabled={false}
  type="submit"
>
  Submit
</IconButton>
